types.D_00006180_s:
struct D_00006180_s {
    s32 unk0;
    u8 pad4[0x24];
    volatile s32 unk28;
    volatile s32 unk2C;
    volatile s32 unk30;
    u8 pad34[0x8];
    volatile s32 unk3C;
};

types.D_0000B3AC_s:
struct D_0000B3AC_s {
    s32 unk0;
    s32 unk4;
    volatile s32 unk8;
    volatile s32 unkC;
    u8 pad10[0x8];
    volatile s32 unk18;
    u8 pad1C[0xC];
    s32 unk28;
