types.ScePowerCallbackCB:
/* A registered power callback slot (1.00: 8 bytes). */
typedef struct {
    SceUID cbid; /* 0x0, < 0: free slot */
    s32 delayedCallbacksAccumulatedOneOffArg; /* 0x4 */
} ScePowerCallbackCB;

types.ScePowerHandlers:
/* sceKernelRegisterPowerHandlers table (1.00: 6 words, 1.02: 7, 1.50: 10). */
typedef struct {
    s32 size;
    s32 (*tick)(s32);
    s32 (*lock)(s32);
    s32 (*unlock)(s32);
    s32 (*lockForUser)(s32);
    s32 (*unlockForUser)(s32);
#if FW_VERSION >= 102
    s32 (*rebootStart)(void);
#endif
#if FW_VERSION >= 150
    s32 (*memLock)(s32, void **, SceSize *);
    s32 (*memTryLock)(s32, void **, SceSize *);
    s32 (*memUnlock)(s32);
#endif
} ScePowerHandlers;

types.ScePowerIdleTimerCb:
/* Idle timer slot (1.00: 0x20 bytes). */
typedef struct {
    u32 isResetted; /* 0x0 */
    s32 isDueTimeReached; /* 0x4, -1 after registration */
    u32 attr; /* 0x8 */
    u32 baseTime; /* 0xC */
    u32 dueTime; /* 0x10 */
    s32 (*callback)(s32 slot, s32 isDue, void *arg); /* 0x14 */
    u32 gp; /* 0x18 */
    void *callbackArg; /* 0x1C */
} ScePowerIdleTimerCb;

types.ScePowerIdle_main:
/* idleTimer.c state (1.00: 0x104 bytes). */
typedef struct {
    u32 curSystemTime; /* 0x0 */
    ScePowerIdleTimerCb idleTimerCb[8]; /* 0x4 */
} ScePowerIdle;

types.ScePowerResume:
/* Suspend/resume save area (1.00 layout, 0x5040 bytes). */
typedef struct {
    u8 scratchpad[0x4000]; /* 0x0 */
    u8 hwResetVector[0x1000]; /* 0x4000, copy of 0xBFC00000 */
    s32 pllOutSelect; /* 0x5000 */
    s32 powerDownCounter; /* 0x5004 */
#if FW_VERSION == 102 || FW_VERSION == 103
    u8 resumeInfo[0x78]; /* 0x5008, ScePowerResumeInfo (size word first) */
#else
    u8 resumeInfo[0x38]; /* 0x5008, ScePowerResumeInfo (size word first) */
#endif
} ScePowerResume;

types.ScePower_main:
/* power.c control block (1.00 layout, 0x108 bytes). */
typedef struct {
    ScePowerCallbackCB powerCallbackCBs[32]; /* 0x0 */
    u32 curPowerStateForCallbackArg; /* 0x100 */
#if FW_VERSION == 102 || FW_VERSION == 103
    u8 wlanActivity; /* 0x104 */
    u8 isWlanSuppressChargingEnabled; /* 0x105, IdStorage key 4 byte 0x19 */
    u8 backlightMaximumWlanActive; /* 0x106, byte 0x1E */
    u8 ledOffTiming; /* 0x107, byte 0x1F (set from 1.03) */
#else
    u32 isWlanSuppressChargingEnabled; /* 0x104, IdStorage key 4 byte 0x19 */
#endif
} ScePower;

types.SceSysEventHandler:
typedef struct SceSysEventHandler {
    s32 size;
    char *name;
    s32 typeMask;
    s32 (*handler)(s32 eventId, char *eventName, void *param, s32 *result);
    s32 gp;
    s32 busy;
    struct SceSysEventHandler *next;
    s32 reserved[9];
} SceSysEventHandler;
